"use client"

import * as React from "react"
import { cn } from "cn"
import {
  Toolbar as ToolbarPrimitive,
  composeRenderProps,
  type ToolbarProps,
} from "react-aria-components"

import { Separator } from "@/components/ui/separator"

function Toolbar({ className, orientation = "horizontal", ...props }: ToolbarProps) {
  return (
    <ToolbarPrimitive
      data-slot="toolbar"
      orientation={orientation}
      className={composeRenderProps(className, (className) =>
        cn(
          "flex w-fit items-center gap-1 rounded-lg border bg-background p-1 data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch",
          className
        )
      )}
      {...props}
    />
  )
}

function ToolbarGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      role="group"
      data-slot="toolbar-group"
      className={cn("flex items-center gap-1", className)}
      {...props}
    />
  )
}

function ToolbarSeparator({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-slot="toolbar-separator"
      orientation={orientation}
      className={cn(
        "relative self-stretch bg-input data-horizontal:mx-px data-horizontal:w-auto data-vertical:my-px data-vertical:h-auto",
        className
      )}
      {...props}
    />
  )
}

export { Toolbar, ToolbarGroup, ToolbarSeparator }
